// Test: Does lexical comparison of ISO dates work for sorting?
void main() {
  final dates = [
    "2025-02-01",
    "2025-01-15", 
    "2025-01-08",
    "2024-12-31",
  ];

  dates.sort((a, b) {
    final x = a;
    final y = b;
    if (x.isEmpty != y.isEmpty) return x.isEmpty ? 1 : -1;
    final nx = num.tryParse(x);
    final ny = num.tryParse(y);
    print('Comparing $x (parsed: $nx) vs $y (parsed: $ny)');
    final c = (nx != null && ny != null) ? nx.compareTo(ny) : x.compareTo(y);
    return c;
  });

  print('Sorted: $dates');
  print('Expected: [2024-12-31, 2025-01-08, 2025-01-15, 2025-02-01]');
}
EOF
